package com.gbkhealthcare.billing;
import com.gbkhealthcare.auth.*;import com.gbkhealthcare.config.SecurityConfig;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.security.oauth2.jwt.*;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest({BillingController.class,AdminBillingController.class}) @Import(SecurityConfig.class)
class BillingControllerSecurityTest{
 @Autowired MockMvc mvc;@MockBean BillingService billing;@MockBean StaffAccessService access;@MockBean JwtDecoder decoder;
 @Test void staffScopeMayReachBillingButRoleIsCheckedInService()throws Exception{when(decoder.decode("staff")).thenReturn(jwt("staff","STAFF"));when(billing.serviceCatalog(any(),eq(false))).thenReturn(java.util.List.of());mvc.perform(get("/api/billing/services").header("Authorization","Bearer staff")).andExpect(status().isOk());verify(billing).serviceCatalog(any(),eq(false));}
 @Test void doctorAndAdminTokensCannotReachStaffBilling()throws Exception{when(decoder.decode("doctor")).thenReturn(jwt("doctor","DOCTOR"));when(decoder.decode("admin")).thenReturn(jwt("admin","ADMIN"));mvc.perform(get("/api/billing/services").header("Authorization","Bearer doctor")).andExpect(status().isForbidden());mvc.perform(get("/api/billing/services").header("Authorization","Bearer admin")).andExpect(status().isForbidden());verifyNoInteractions(billing);}
 @Test void onlyAdminScopeCanReachAdminBilling()throws Exception{when(decoder.decode("admin")).thenReturn(jwt("admin","ADMIN"));when(decoder.decode("staff")).thenReturn(jwt("staff","STAFF"));when(billing.adminInvoices(any())).thenReturn(java.util.List.of());mvc.perform(get("/api/admin/billing/invoices").header("Authorization","Bearer staff")).andExpect(status().isForbidden());mvc.perform(get("/api/admin/billing/invoices").header("Authorization","Bearer admin")).andExpect(status().isOk());verify(billing).adminInvoices(any());}
 private static Jwt jwt(String token,String scope){return Jwt.withTokenValue(token).header("alg","HS256").subject("user@example.test").claim("scope",scope).build();}
}
